63	// startServer 在 dataDir 上启动真实服务子进程（--port 0 自动选端口），返回基地址。
64	function startServer(t, dataDir) {
65	  const proc = spawn(
66	    serverBin,
67	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
68	    { stdio: ['ignore', 'pipe', 'inherit'] },
69	  );
70	  t.after(() => { proc.kill('SIGKILL'); });
71	  return new Promise((resolve, reject) => {
72	    let buf = '';
73	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
74	    proc.stdout.on('data', (chunk) => {
75	      buf += chunk.toString();
76	      const m = buf.match(/listening on (http:\/\/\S+)/);
77	      if (m) {
78	        clearTimeout(timer);
79	        resolve(m[1]);
80	      }
81	    });
82	    proc.on('exit', (code) => {
83	      clearTimeout(timer);
84	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
85	    });
86	  });
87	}
