366	  // 第二个名称带脚本样式文字（27 个码点），若被当成脚本元素会尝试弹窗。
367	  const nameScript = '"><script>alert(1)</script>';
368	  assert.ok([...nameScript].length <= 40);
369	  createdPromise = nextCreated(page);
370	  await fillGomokuForm(page, nameScript, 0);
371	  await page.click('#submit');
372	  await waitForMessageKind(page, 'ok');
373	  const createdScript = await createdPromise;
374	  assert.equal(createdScript.name, nameScript, '脚本样式文字应作为名称原文保存');
375	
376	  await waitForRowCount(page, 4);
377	  nameCell = await readNameCell(page, 3);
378	  assert.equal(nameCell.text, nameScript, '脚本样式名称应逐字可读');
379	  assert.equal(nameCell.childElements, 0, '名称不应变成脚本等元素');
380	
381	  // 给潜在的事件处理与脚本留出执行窗口后统一断言：
382	  // 没有弹窗、没有标记变量被写入、页面没有跳转、列表区域没有多余元素。
383	  await new Promise((resolve) => setTimeout(resolve, 500));
384	  assert.deepEqual(dialogs, [], '名称中的内容不应引发任何弹窗');
385	  assert.equal(
386	    await page.evaluate(() => window.__pwned),
387	    undefined,
388	    '名称中的事件处理内容不应被执行',
389	  );
390	  assert.equal(page.url(), baseURL + '/', '名称中的内容不应引发页面跳转');
391	  assert.equal(await countListAreaElements(page, 'img'), 0, '名称不应变成图片');
392	  assert.equal(await countListAreaElements(page, 'script'), 0, '名称不应产生脚本元素');
393	  assert.equal(await countListAreaElements(page, 'iframe'), 0, '名称不应产生框架元素');
394	  assert.equal(await countListAreaElements(page, 'button'), 0, '名称不应变成额外按钮');
395	
396	  // 两个新房间的名称在列表接口中同样逐字一致，已有房间行不受影响。
397	  const rows = await readRows(page);
398	  assertSeedRows(rows.slice(0, 2));
399	  assert.equal(rows[2].cells[1], nameImg);
400	  assert.equal(rows[3].cells[1], nameScript);
401	  const serverRooms = await readServerRooms(baseURL);
402	  assert.deepEqual(
403	    serverRooms.map((r) => r.name),
404	    [SEED_ALPHA_NAME, SEED_BETA_NAME, nameImg, nameScript],
405	    '列表接口中的名称应全部逐字一致',
406	  );
407	});
408	
409	// 名称本来包含类似网页字符实体的文字（&lt;、&amp; 等）：显示这段文字原有
410	// 的写法，不能再次解释成另一种字符；普通标点与标签样式文字混在一起时同样
411	// 保留完整名称。已有记录中的实体样式名称在首次打开与列表更新后都保持原文。
412	test('实体样式文字按原有写法显示，不再解释成另一种字符', { timeout: 60000 }, async (t) => {
413	  const { page, baseURL } = await setupPage(t);
414	
415	  // 首次打开：已有记录里的实体样式名称按原有写法逐字显示，
416	  // 不能被解释成 <img src=x>，也不能变成图片元素。
417	  const initialRows = await readRows(page);
418	  assertSeedRows(initialRows);
419	  let seedBetaCell = await readNameCell(page, 1);
420	  assert.equal(seedBetaCell.text, '&lt;img src=x&gt; 午夜五子棋', '实体样式文字应按原有写法显示');
421	  assert.ok(!seedBetaCell.text.includes('<img'), '实体样式文字不应被解释成标签');
422	  assert.equal(seedBetaCell.childElements, 0, '实体样式名称不应变成任何网页元素');
423	  assert.equal(await countListAreaElements(page, 'img'), 0, '实体样式名称不应变成图片');
424	
425	  // 新建名称：实体样式文字与普通标点、中文混合（整理后 26 个码点）。
426	  const createdPromise = nextCreated(page);
427	  const rawName = '  &lt;b&gt;棋&lt;/b&gt; &amp; "友"  ';
428	  const trimmedName = '&lt;b&gt;棋&lt;/b&gt; &amp; "友"';
429	  assert.ok([...trimmedName].length <= 40);
430	  await fillGomokuForm(page, rawName, 0);
431	  await page.click('#submit');
432	
433	  await waitForMessageKind(page, 'ok');
434	  const created = await createdPromise;
435	  // 创建结果中的名称与整理后的原文一致：&lt; 是名称内容本身，
436	  // 不是页面显示用的转义写法，服务端不得再加工。
437	  assert.equal(created.name, trimmedName, '实体样式文字应作为名称原文保存');
438	
439	  const msg = await readMessage(page);
440	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id, '成功提示应显示本次编号');
441	
442	  // 列表更新后：新名称逐字显示原有的实体写法（&lt; 显示为四个字符 &lt;），
443	  // 不能再次解释成 <b> 或加粗元素；innerHTML 中的双重转义恰好证明
444	  // 浏览器只把它当普通文字。
445	  await waitForRowCount(page, 3);
446	  const nameCell = await readNameCell(page, 2);
447	  assert.equal(nameCell.text, trimmedName, '实体样式名称应逐字显示原有写法');
448	  assert.ok(!nameCell.text.includes('<b>'), '实体样式文字不应被再次解释成标签');
449	  assert.equal(nameCell.childElements, 0, '实体样式名称不应变成加粗等元素');
450	  assert.ok(nameCell.innerHTML.includes('&amp;lt;'), '实体写法在页面中应再转义一层以保持原文显示');
451	  assert.equal(await countListAreaElements(page, 'b'), 0, '实体样式名称不应变成加粗文字');
452	
453	  // 列表更新后已有行的实体样式名称仍保持原文，相对次序与其他配置不变。
454	  const rows = await readRows(page);
455	  assertSeedRows(rows.slice(0, 2));
456	  seedBetaCell = await readNameCell(page, 1);
457	  assert.equal(seedBetaCell.text, '&lt;img src=x&gt; 午夜五子棋', '列表更新后已有名称仍应保持原文');
458	  assert.equal(seedBetaCell.childElements, 0);
459	
460	  // 列表接口中的名称同样逐字一致。
461	  const serverRooms = await readServerRooms(baseURL);
462	  assert.equal(serverRooms.length, 3);
463	  assert.equal(serverRooms[1].name, SEED_BETA_NAME, '已有记录的名称不应被改写');
464	  assert.equal(serverRooms[2].name, trimmedName);
465	});
466	
467	// 已有房间记录中的标签样式字符串名称：首次打开首页按原文展示；随后新建
468	// 房间导致列表更新时仍保持原文，已有行的相对次序与其他配置不变；查看
469	// 这样的名称不改写已有记录，新房间只追加一条正常房间记录。
470	test('已有记录中的标签样式名称：查看与新建都不改写，列表更新后仍按原文展示', { timeout: 60000 }, async (t) => {
471	  const { page, baseURL, dataDir } = await setupPage(t);
472	
473	  // 首次打开：已有名称逐字展示（含尖括号、引号、与号），不变成网页元素。
474	  const initialRows = await readRows(page);
475	  assertSeedRows(initialRows);
476	  const seedAlphaCell = await readNameCell(page, 0);
477	  assert.equal(seedAlphaCell.text, SEED_ALPHA_NAME, '已有标签样式名称应逐字展示');
478	  assert.equal(seedAlphaCell.childElements, 0, '已有名称不应变成加粗等元素');
479	  assert.equal(await countListAreaElements(page, 'b'), 0, '已有名称不应变成加粗文字');
480	
481	  // 仅仅查看这样的名称不改写已有记录：本地文件与写入时逐字节一致。
482	  const seededContent = '[\n' + SEED_ALPHA + ',\n' + SEED_BETA + '\n]\n';
483	  assert.equal(
484	    await readFile(path.join(dataDir, 'rooms.json'), 'utf8'),
485	    seededContent,
486	    '查看已有名称不应改写本地记录',
487	  );
488	
489	  // 新建一个普通名称的房间，触发列表更新。
490	  const createdPromise = nextCreated(page);
491	  await fillGomokuForm(page, '  新建 棋室  ', 0);
492	  await page.click('#submit');
493	  await waitForMessageKind(page, 'ok');
494	  const created = await createdPromise;
495	  assert.equal(created.name, '新建 棋室');
496	  const msg = await readMessage(page);
497	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id, '成功提示应显示本次编号');
498	
499	  // 列表更新后：已有行仍按原文展示，相对次序与其他配置不变，新行追加在后。
500	  await waitForRowCount(page, 3);
501	  const rows = await readRows(page);
502	  assert.deepEqual(rows.slice(0, 2), initialRows, '已有行的内容或次序不应改变');
503	  const seedAlphaCellAfter = await readNameCell(page, 0);
504	  assert.equal(seedAlphaCellAfter.text, SEED_ALPHA_NAME, '列表更新后已有名称仍应逐字展示');
505	  assert.equal(seedAlphaCellAfter.childElements, 0);
506	  assert.equal(rows[2].cells[0], created.id);
507	  assert.equal(rows[2].cells[1], '新建 棋室');
508	
509	  // 服务端与本地：已有记录（含附带字段）逐字保持原值，
510	  // 新房间只追加一条正常记录（编号非空、状态 waiting、公开范围 public）。
511	  const serverRooms = await readServerRooms(baseURL);
512	  assert.equal(serverRooms.length, 3, '新房间应只追加一条记录');
513	  assert.deepEqual(serverRooms[0], JSON.parse(SEED_ALPHA), '已有记录不应被改写');
514	  assert.deepEqual(serverRooms[1], JSON.parse(SEED_BETA), '已有记录不应被改写');
515	  assert.equal(serverRooms[2].id, created.id);
516	  assert.equal(serverRooms[2].status, 'waiting');
517	  assert.equal(serverRooms[2].visibility, 'public');
518	
519	  const savedRooms = JSON.parse(await readFile(path.join(dataDir, 'rooms.json'), 'utf8'));
520	  assert.equal(savedRooms.length, 3, '本地文件应只追加一条记录');
521	  assert.deepEqual(savedRooms[0], JSON.parse(SEED_ALPHA), '本地已有记录不应被改写');
522	  assert.deepEqual(savedRooms[1], JSON.parse(SEED_BETA), '本地已有记录不应被改写');
523	});
